-- GAS-CP-R92-003 — screening set for Project Managers (PM-STD-8). Scores never leave the server; HR edits it under Recruiting › Screening sets.
INSERT IGNORE INTO rc_screening_sets (code, title, pass_threshold, knockout_groups, questions) VALUES ('PM-STD-8', 'Project Managers — delivery mindset & commitment (8 questions)', 7, 'loyalty', JSON_ARRAY(
 JSON_OBJECT('id','q1','group','planning','text','You take over a refit project with an electrical scope that is only half defined and a fixed delivery date. Your first week goes to…','options',JSON_ARRAY(JSON_OBJECT('id','a','text','Freezing the scope with the yard and owner, building the schedule backwards from the trials and naming the long-lead items.','score',1),JSON_OBJECT('id','b','text','Starting the work that is clear and sorting the rest out as it comes.','score',0),JSON_OBJECT('id','c','text','A short list of open points with owners and dates, then a baseline plan everyone signs.','score',1))),
 JSON_OBJECT('id','q2','group','stakeholders','text','The yard changes the cable-route sequence and the owner''s representative asks for extra functions, both on the same day. You…','options',JSON_ARRAY(JSON_OBJECT('id','a','text','Say yes to both to keep the relationship good and absorb the cost.','score',0),JSON_OBJECT('id','b','text','Assess the impact on hours, parts and dates, then answer each in writing with a variation where it applies.','score',1),JSON_OBJECT('id','c','text','Bring both parties to one table, agree priorities and record the decision in the project log.','score',1))),
 JSON_OBJECT('id','q3','group','cost','text','Half-way through a project the hours are at 70 % of budget and the cabinets are not yet installed. What do you do?','options',JSON_ARRAY(JSON_OBJECT('id','a','text','Report it now with a forecast to completion and a recovery plan, even if the news is unwelcome.','score',1),JSON_OBJECT('id','b','text','Wait — it usually evens out towards commissioning.','score',0),JSON_OBJECT('id','c','text','Re-plan the remaining work with the lead engineer and move resources before the overrun becomes fact.','score',1))),
 JSON_OBJECT('id','q4','group','risk','text','A maker confirms a 14-week lead time on a main switchboard breaker that the plan assumed in 6. Your reaction:','options',JSON_ARRAY(JSON_OBJECT('id','a','text','Look for an equivalent approved by class, check the delivery options and raise the risk with the yard the same day.','score',1),JSON_OBJECT('id','b','text','Note it and hope the yard slips too.','score',0),JSON_OBJECT('id','c','text','Re-sequence the installation so the late item is the last one fitted, and keep the trials date.','score',1))),
 JSON_OBJECT('id','q5','group','class','text','How do you treat class approval drawings, test records and as-built documentation?','options',JSON_ARRAY(JSON_OBJECT('id','a','text','As deliverables with their own dates in the plan — a vessel without approved documents is not delivered.','score',1),JSON_OBJECT('id','b','text','As paperwork to catch up on after the ship sails.','score',0),JSON_OBJECT('id','c','text','I follow the submission status with the surveyor and keep the document register current week by week.','score',1))),
 JSON_OBJECT('id','q6','group','team','text','Two of your engineers disagree on how a fault should be fixed, in front of the yard foreman. You…','options',JSON_ARRAY(JSON_OBJECT('id','a','text','Take the discussion aside, hear both, decide on the evidence and back the decision publicly.','score',1),JSON_OBJECT('id','b','text','Let them argue it out; the strongest opinion is usually right.','score',0),JSON_OBJECT('id','c','text','Decide quickly, explain the reasoning to both and follow up afterwards so it does not repeat.','score',1))),
 JSON_OBJECT('id','q7','group','loyalty','text','Looking back at your roles, what best describes your typical tenure?','options',JSON_ARRAY(JSON_OBJECT('id','a','text','Several years each — I commit and see projects through to delivery and warranty.','score',1),JSON_OBJECT('id','b','text','Long tenures, with moves driven by genuine growth, not restlessness.','score',1),JSON_OBJECT('id','c','text','Often under a year — I tend to move on quickly and frequently.','score',0))),
 JSON_OBJECT('id','q8','group','loyalty','text','Golden invests in its project managers (training, class and maker courses, responsibility for complete vessels). What would make you stay long-term?','options',JSON_ARRAY(JSON_OBJECT('id','a','text','Complete projects I can own end to end, a team I respect and a clear path forward.','score',1),JSON_OBJECT('id','b','text','Whatever pays most at any given moment; I would leave the day a better offer appears.','score',0),JSON_OBJECT('id','c','text','Growing responsibility and the company investing in my development.','score',1)))
));
